INSERT INTO public.kb_blocos (id, documento_id, tipo, conteudo, ordem, tenant_id) VALUES ('dead7c6e-edbe-4c38-8045-f7169e03a177'::uuid, '54b73083-608a-4ff9-8faa-a9a673ecadbe'::uuid, 'callout', '{"texto": "Primeiro perfume automotivo premium do Brasil. Single SKU, frasco transparente, líquido transparente, tampa prateada escovada, essência inspirada no Creed Aventus.", "emoji": "✨"}'::jsonb, 1, 'a1b2c3d4-e5f6-7890-abcd-ef1234567890') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.kb_blocos (id, documento_id, tipo, conteudo, ordem, tenant_id) VALUES ('bf185eb5-2c6e-4e17-821a-1c93db2b4643'::uuid, '54b73083-608a-4ff9-8faa-a9a673ecadbe'::uuid, 'subtitulo', '{"texto": "Posicionamento"}'::jsonb, 2, 'a1b2c3d4-e5f6-7890-abcd-ef1234567890') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.kb_blocos (id, documento_id, tipo, conteudo, ordem, tenant_id) VALUES ('23c47643-bbcf-4eab-82c1-0296ad2b2841'::uuid, '54b73083-608a-4ff9-8faa-a9a673ecadbe'::uuid, 'paragrafo', '{"texto": "A PURION não compete com aromatizantes de carro genéricos — ela cria uma categoria acima. Onde Estilo Motors, Areon e Aromá são funcionais e commodity, a PURION ocupa o território sensorial premium que esses players ignoram completamente."}'::jsonb, 3, 'a1b2c3d4-e5f6-7890-abcd-ef1234567890') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.kb_blocos (id, documento_id, tipo, conteudo, ordem, tenant_id) VALUES ('5df30f79-d040-4659-8b8d-69e1c6e7f24c'::uuid, '54b73083-608a-4ff9-8faa-a9a673ecadbe'::uuid, 'paragrafo', '{"texto": "A marca não substitui o que existe; cria um degrau acima. Perfume automotivo de assinatura, não \"cheirinho de carro\"."}'::jsonb, 4, 'a1b2c3d4-e5f6-7890-abcd-ef1234567890') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.kb_blocos (id, documento_id, tipo, conteudo, ordem, tenant_id) VALUES ('70b8ea73-4f5e-4139-8faf-97a8059503ba'::uuid, '54b73083-608a-4ff9-8faa-a9a673ecadbe'::uuid, 'subtitulo', '{"texto": "Produto (constraint absoluta)"}'::jsonb, 5, 'a1b2c3d4-e5f6-7890-abcd-ef1234567890') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.kb_blocos (id, documento_id, tipo, conteudo, ordem, tenant_id) VALUES ('dec7749e-3988-4519-889d-efa3ec590cb1'::uuid, '54b73083-608a-4ff9-8faa-a9a673ecadbe'::uuid, 'lista', '{"itens": ["Frasco 60ml de vidro transparente", "Líquido transparente (NUNCA dourado/âmbar)", "Tampa prateada escovada", "Wordmark PURION em preto, \"O\" estilizado, \"GT\" em serifa itálica", "Essência inspirada no Creed Aventus: frutal-amadeirada-masculina", "Notas: topo abacaxi/bergamota/cassis · coração bétula/pimenta-rosa/jasmim · fundo musk/âmbar cinza/carvalho/baunilha"]}'::jsonb, 6, 'a1b2c3d4-e5f6-7890-abcd-ef1234567890') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.kb_blocos (id, documento_id, tipo, conteudo, ordem, tenant_id) VALUES ('2aabd094-5d69-41a8-8c19-75e32d963f98'::uuid, '54b73083-608a-4ff9-8faa-a9a673ecadbe'::uuid, 'subtitulo', '{"texto": "Território visual"}'::jsonb, 7, 'a1b2c3d4-e5f6-7890-abcd-ef1234567890') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.kb_blocos (id, documento_id, tipo, conteudo, ordem, tenant_id) VALUES ('810d3206-8244-4fb9-8621-aeb6ffd7b885'::uuid, '54b73083-608a-4ff9-8faa-a9a673ecadbe'::uuid, 'paragrafo', '{"texto": "Pretos profundos, beges quentes, metais escovados, dourados discretos, cinzas frios. Referências: Jo Malone, Aesop, Byredo, Maison Margiela Replica. Nunca aquático, frio ou cristalino — o Aventus é quente e frutal-amadeirado."}'::jsonb, 8, 'a1b2c3d4-e5f6-7890-abcd-ef1234567890') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.kb_blocos (id, documento_id, tipo, conteudo, ordem, tenant_id) VALUES ('545df0ba-9c3b-40d9-89b2-f894e80ae178'::uuid, '54b73083-608a-4ff9-8faa-a9a673ecadbe'::uuid, 'subtitulo', '{"texto": "Proibições da marca"}'::jsonb, 9, 'a1b2c3d4-e5f6-7890-abcd-ef1234567890') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.kb_blocos (id, documento_id, tipo, conteudo, ordem, tenant_id) VALUES ('25b468dd-9474-4c9c-8b48-18915cb03d6b'::uuid, '54b73083-608a-4ff9-8faa-a9a673ecadbe'::uuid, 'checklist', '{"itens": [{"texto": "Sem descontos públicos (só value-adds: frete grátis, cartão à mão)", "feito": false}, {"texto": "Sem mecânica de infoproduto (countdown, urgência empilhada, bônus)", "feito": false}, {"texto": "Sem líquido dourado em nenhum criativo", "feito": false}, {"texto": "Sem prometer ser \"igual\" ao Aventus — é \"inspirado\"", "feito": false}]}'::jsonb, 10, 'a1b2c3d4-e5f6-7890-abcd-ef1234567890') ON CONFLICT (id) DO NOTHING;
